const tabId = 1675924663;

async function searchDDG(query) {
  await tool.navigate({ tabId, url: `https://html.duckduckgo.com/html/?q=${encodeURIComponent(query)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 6000 });
  return await browserjs(tabId, () => {
    const results = [];
    const elements = document.querySelectorAll(".result");
    for (const el of elements) {
      const a = el.querySelector(".result__snippet");
      const titleEl = el.querySelector(".result__title a");
      const urlEl = el.querySelector(".result__url");
      if (titleEl) {
        results.push({
          title: titleEl.textContent.trim(),
          snippet: a ? a.textContent.trim() : "",
          url: urlEl ? urlEl.textContent.trim() : ""
        });
      }
    }
    return results.slice(0, 5);
  });
}

const legQueries = [
  "site:travelchinaguide.com chongqing to zhangjiajie train",
  "site:travelchinaguide.com zhangjiajie to guilin train",
  "site:travelchinaguide.com beijing to xian train",
  "site:travelchinaguide.com xian to chengdu train",
  "site:travelchinaguide.com chengdu to chongqing train"
];

for (const q of legQueries) {
  const res = await searchDDG(q);
  console.log("=== QUERY:", q, "===");
  res.forEach(r => console.log(r.title, "|", r.url, "\nSnippet:", r.snippet));
}

