const tabId = 1675924666;

// Let's verify attraction tickets for major sites using TravelChinaGuide
const attractions = [
  { city: "Beijing", site: "Forbidden City", query: "site:travelchinaguide.com forbidden city ticket price" },
  { city: "Xi'an", site: "Terracotta Army", query: "site:travelchinaguide.com terracotta army ticket price" },
  { city: "Chengdu", site: "Panda Base", query: "site:travelchinaguide.com chengdu giant panda base ticket" },
  { city: "Zhangjiajie", site: "National Forest Park", query: "site:travelchinaguide.com zhangjiajie national forest park ticket" },
  { city: "Guilin/Yangshuo", site: "Yulong River & Reed Flute", query: "site:travelchinaguide.com yangshuo yulong river bamboo raft price" },
  { city: "Hangzhou", site: "Lingyin Temple", query: "site:travelchinaguide.com hangzhou lingyin temple entrance fee" }
];

const results = [];
for (const item of attractions) {
  await tool.navigate({ tabId, url: `https://html.duckduckgo.com/html/?q=${encodeURIComponent(item.query)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 6000 });
  const hit = await browserjs(tabId, () => {
    const res = document.querySelector(".result");
    if (!res) return null;
    const title = res.querySelector(".result__title a")?.innerText.trim();
    const snippet = res.querySelector(".result__snippet")?.innerText.trim();
    const url = res.querySelector(".result__url")?.innerText.trim();
    return { title, snippet, url };
  });
  results.push({ ...item, hit });
}

console.log("Attraction search results:", JSON.stringify(results, null, 2));

